using AeroCompliance.ApiService.Authorization; using AeroCompliance.ApiService.Services; using AeroCompliance.Contracts.Dtos.Common; using AeroCompliance.Contracts.Dtos.Gis; using AeroCompliance.Domain.Entities; using AeroCompliance.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AeroCompliance.ApiService.Controllers;
[ApiController,Route("api/zoning-rules"),Authorize] public sealed class ZoningRulesController(AeroComplianceDbContext db,ICurrentUserContext user,IAuditService audit):ControllerBase
{
 [HttpGet] public async Task<ActionResult<PagedResponse<ZoningRuleDto>>> List(int page=1,int pageSize=25,Guid? municipalityId=null,Guid? zoneId=null,string? search=null,bool? isActive=null,bool? isValidated=null,CancellationToken ct=default){if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination");var q=Visible().AsNoTracking();if(user.IsPlatformAdmin&&municipalityId.HasValue)q=q.Where(x=>x.MunicipalityId==municipalityId);if(zoneId.HasValue)q=q.Where(x=>x.ZoneId==zoneId);var s=ApiSupport.NormalizeSearch(search);if(s is not null)q=q.Where(x=>x.RuleKey.ToLower().Contains(s)||(x.ZoneType!=null&&x.ZoneType.ToLower().Contains(s)));if(isActive.HasValue)q=q.Where(x=>x.IsActive==isActive);if(isValidated.HasValue)q=q.Where(x=>x.IsValidated==isValidated);return Ok(await q.OrderBy(x=>x.RuleKey).Select(MapExpr()).ToPagedAsync(page,pageSize,ct));}
 [HttpGet("{id:guid}")] public async Task<ActionResult<ZoningRuleDto>> Get(Guid id,CancellationToken ct){var x=await Visible().AsNoTracking().Where(x=>x.Id==id).Select(MapExpr()).SingleOrDefaultAsync(ct);return x is null?NotFound():Ok(x);}
 [HttpPost,Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<ZoningRuleDto>> Create(SaveZoningRuleRequest r,CancellationToken ct){if(!ValidTarget(r))return Problem(statusCode:400,title:"Invalid rule target",detail:"Specify exactly one of zoneId or zoneType.");var tenant=await ResolveTenant(r,ct);if(tenant is null)return NotFound();var x=new ZoningRule{Id=Guid.NewGuid(),MunicipalityId=tenant.Value,ZoneId=r.ZoneId,ZoneType=r.ZoneType?.Trim(),RuleKey=r.RuleKey.Trim(),RuleValue=r.RuleValue,Unit=r.Unit.Trim(),SourceDocument=r.SourceDocument?.Trim(),ExtractedByAi=r.ExtractedByAi,IsValidated=false,IsActive=r.IsActive,CreatedAt=DateTimeOffset.UtcNow};db.ZoningRules.Add(x);audit.Add("zoning_rule.create","ZoningRule",x.Id,after:new{x.MunicipalityId,x.ZoneId,x.ZoneType,x.RuleKey,x.RuleValue,x.Unit,x.IsActive});await db.SaveChangesAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},await Reload(x.Id,ct));}
 [HttpPut("{id:guid}"),Authorize(Policy=Policies.ManageGis)] public async Task<ActionResult<ZoningRuleDto>> Update(Guid id,SaveZoningRuleRequest r,CancellationToken ct){var x=await Visible().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();if(!ValidTarget(r))return Problem(statusCode:400,title:"Invalid rule target",detail:"Specify exactly one of zoneId or zoneType.");if(r.ZoneId.HasValue&&!await db.Zones.AnyAsync(z=>z.Id==r.ZoneId&&z.MunicipalityId==x.MunicipalityId,ct))return NotFound();if(user.IsPlatformAdmin&&r.MunicipalityId.HasValue&&r.MunicipalityId!=x.MunicipalityId)return Problem(statusCode:409,title:"Conflict",detail:"A rule cannot be moved between municipalities.");var before=new{x.ZoneId,x.ZoneType,x.RuleKey,x.RuleValue,x.Unit,x.SourceDocument,x.ExtractedByAi,x.IsActive,x.IsValidated};x.ZoneId=r.ZoneId;x.ZoneType=r.ZoneType?.Trim();x.RuleKey=r.RuleKey.Trim();x.RuleValue=r.RuleValue;x.Unit=r.Unit.Trim();x.SourceDocument=r.SourceDocument?.Trim();x.ExtractedByAi=r.ExtractedByAi;x.IsActive=r.IsActive;x.IsValidated=false;x.ValidatedBy=null;x.ValidatedAt=null;audit.Add("zoning_rule.update","ZoningRule",id,before,new{x.ZoneId,x.ZoneType,x.RuleKey,x.RuleValue,x.Unit,x.SourceDocument,x.ExtractedByAi,x.IsActive,x.IsValidated});await db.SaveChangesAsync(ct);return Ok(await Reload(id,ct));}
 [HttpPost("{id:guid}/validate"),Authorize(Policy=Policies.AnalyzeGis)] public async Task<ActionResult<ZoningRuleDto>> Validate(Guid id,CancellationToken ct){var x=await Visible().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();if(user.UserId is not Guid actor)return Unauthorized();var before=new{x.IsValidated,x.ValidatedBy,x.ValidatedAt};x.IsValidated=true;x.ValidatedBy=actor;x.ValidatedAt=DateTimeOffset.UtcNow;audit.Add("zoning_rule.validate","ZoningRule",id,before,new{x.IsValidated,x.ValidatedBy,x.ValidatedAt});await db.SaveChangesAsync(ct);return Ok(await Reload(id,ct));}
 private IQueryable<ZoningRule> Visible()=>user.IsPlatformAdmin?db.ZoningRules:db.ZoningRules.Where(x=>x.MunicipalityId==user.MunicipalityId);private static bool ValidTarget(SaveZoningRuleRequest r)=>r.ZoneId.HasValue^!string.IsNullOrWhiteSpace(r.ZoneType);private async Task<Guid?> ResolveTenant(SaveZoningRuleRequest r,CancellationToken ct){var tenant=user.IsPlatformAdmin?r.MunicipalityId:user.MunicipalityId;if(tenant is null)return null;if(r.ZoneId.HasValue)return await db.Zones.AnyAsync(x=>x.Id==r.ZoneId&&x.MunicipalityId==tenant,ct)?tenant:null;return await db.Municipalities.AnyAsync(x=>x.Id==tenant,ct)?tenant:null;}
 // Re-reads through the same tenant-scoped, name-projecting query used by GET, so a mutation's response
 // always reflects the just-saved Zone/Validator names rather than stale/unloaded navigation properties.
 private Task<ZoningRuleDto> Reload(Guid id,CancellationToken ct)=>Visible().AsNoTracking().Where(x=>x.Id==id).Select(MapExpr()).SingleAsync(ct);
 private static System.Linq.Expressions.Expression<Func<ZoningRule,ZoningRuleDto>> MapExpr()=>x=>new(x.Id,x.MunicipalityId,x.ZoneId,x.Zone!=null?x.Zone.ZoneNumber:null,x.ZoneType,x.RuleKey,x.RuleValue,x.Unit,x.SourceDocument,x.ExtractedByAi,x.IsValidated,x.ValidatedBy,x.Validator!=null?x.Validator.FullName:null,x.ValidatedAt,x.IsActive,x.CreatedAt);
}
